import{_ as a,f as n,o as e,aq as l}from"./chunks/framework.D7yxI9Ht.js";const u=JSON.parse('{"title":"Package Development","description":"","frontmatter":{},"headers":[],"relativePath":"digging-deeper/package-development.md","filePath":"en/digging-deeper/package-development.md","lastUpdated":1789751181000}'),o={name:"digging-deeper/package-development.md"};function p(r,s,t,c,i,y){return e(),n("div",null,s[0]||(s[0]=[l(`<h1 id="package-development" tabindex="-1">Package Development <a class="header-anchor" href="#package-development" aria-label="Permalink to “Package Development”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>Packages are the primary way of adding functionality to Goravel. These packages may contain routes, controllers, and configurations that are specifically designed to enhance a Goravel application. This guide focuses on developing Goravel-specific packages.</p><p>Here is an example for building a third-party package: <a href="https://github.com/goravel/example-package" target="_blank" rel="noreferrer">goravel/example-package</a></p><h2 id="creating-a-package" tabindex="-1">Creating A Package <a class="header-anchor" href="#creating-a-package" aria-label="Permalink to “Creating A Package”">​</a></h2><p>You can use easily create a package template using the Artisan command:</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#0077B3;">./artisan</span><span style="color:#101820;"> make:package</span><span style="color:#101820;"> sms</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The created files are saved by default in the root <code>packages</code> folder, you can use <code>--root</code> option to customize:</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#0077B3;">./artisan</span><span style="color:#101820;"> make:package</span><span style="color:#101820;"> --root=pkg</span><span style="color:#101820;"> sms</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="service-providers" tabindex="-1">Service Providers <a class="header-anchor" href="#service-providers" aria-label="Permalink to “Service Providers”">​</a></h2><p><a href="./../architecture-concepts/service-providers.html">Service providers</a> act as the bridge between your package and Goravel. They are typically located in the root of the package as a <code>service_provider.go</code> file. Their main function is to bind items into Goravel&#39;s service container and guide Goravel in loading package resources.</p><h2 id="install-the-package" tabindex="-1">Install The Package <a class="header-anchor" href="#install-the-package" aria-label="Permalink to “Install The Package”">​</a></h2><p>When creating a package, if it contains a <code>setup/setup.go</code> file, you can define the package installation logic in this file, and then users can use the <code>package:install</code> command to install the package:</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#0077B3;">./artisan</span><span style="color:#101820;"> package:install</span><span style="color:#101820;"> github.com/goravel/example-package</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The following is an explanation of the installation process defined in the <code>setup/setup.go</code> file, which helps you write your own package installation logic:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">setup/setup.go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">package main</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#68747D;">	&quot;</span><span style="color:#101820;">os</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">	&quot;</span><span style="color:#101820;">github.com/goravel/framework/packages</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">	&quot;</span><span style="color:#101820;">github.com/goravel/framework/packages/modify</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">	&quot;</span><span style="color:#101820;">github.com/goravel/framework/support/file</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">	&quot;</span><span style="color:#101820;">github.com/goravel/framework/support/path</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#0077B3;">main</span><span style="color:#68747D;">()</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#68747D;">	// Initialize setup to get paths, this should be called at the beginning.</span></span>
<span class="line"><span style="color:#101820;">	setup </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> packages</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Setup</span><span style="color:#68747D;">(</span><span style="color:#101820;">os</span><span style="color:#68747D;">.</span><span style="color:#101820;">Args</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">	// The config file will be published to the project&#39;s config directory automatically when installing by this way.</span></span>
<span class="line"><span style="color:#68747D;">	// You can also publish this config file manually: ./artisan vendor:publish --package=github.com/goravel/example-package</span></span>
<span class="line"><span style="color:#101820;">	config</span><span style="color:#68747D;">,</span><span style="color:#101820;"> err </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> file</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">GetPackageContent</span><span style="color:#68747D;">(</span><span style="color:#101820;">setup</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Paths</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Module</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">String</span><span style="color:#68747D;">(),</span><span style="color:#68747D;"> &quot;setup/config/hello.go&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#101820;">	if err </span><span style="color:#68747D;">!=</span><span style="color:#101820;"> nil </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#0077B3;">		panic</span><span style="color:#68747D;">(</span><span style="color:#101820;">err</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#68747D;">	}</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">	serviceProvider </span><span style="color:#68747D;">:=</span><span style="color:#68747D;"> &quot;&amp;hello.ServiceProvider{}&quot;</span></span>
<span class="line"><span style="color:#101820;">	moduleImport </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> setup</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Paths</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Module</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Import</span><span style="color:#68747D;">()</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">	setup</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Install</span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#68747D;">		// Register the service provider to the providers slice in bootstrap/providers.go</span></span>
<span class="line"><span style="color:#101820;">		modify</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">RegisterProvider</span><span style="color:#68747D;">(</span><span style="color:#101820;">moduleImport</span><span style="color:#68747D;">,</span><span style="color:#101820;"> serviceProvider</span><span style="color:#68747D;">),</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">		// Add the config file to the config directory</span></span>
<span class="line"><span style="color:#101820;">		modify</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">File</span><span style="color:#68747D;">(</span><span style="color:#101820;">path</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Config</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;hello.go&quot;</span><span style="color:#68747D;">)).</span><span style="color:#0077B3;">Overwrite</span><span style="color:#68747D;">(</span><span style="color:#101820;">config</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">	).</span><span style="color:#0077B3;">Uninstall</span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#68747D;">		// Remove the config file from the config directory</span></span>
<span class="line"><span style="color:#101820;">		modify</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">File</span><span style="color:#68747D;">(</span><span style="color:#101820;">path</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Config</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;hello.go&quot;</span><span style="color:#68747D;">)).</span><span style="color:#0077B3;">Remove</span><span style="color:#68747D;">(),</span></span>
<span class="line"></span>
<span class="line"><span style="color:#68747D;">		// Unregister the service provider from the providers slice in bootstrap/providers.go</span></span>
<span class="line"><span style="color:#101820;">		modify</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">UnregisterProvider</span><span style="color:#68747D;">(</span><span style="color:#101820;">moduleImport</span><span style="color:#68747D;">,</span><span style="color:#101820;"> serviceProvider</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">	).</span><span style="color:#0077B3;">Execute</span><span style="color:#68747D;">()</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br></div></div><p>If the package import path is long or its default package name is not convenient, setup modify helpers support an import alias in the <code>&quot;&lt;alias&gt; &lt;import-path&gt;&quot;</code> format. Use the same aliased import string when installing and uninstalling:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">func </span><span style="color:#0077B3;">main</span><span style="color:#68747D;">()</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">	setup </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> packages</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Setup</span><span style="color:#68747D;">(</span><span style="color:#101820;">os</span><span style="color:#68747D;">.</span><span style="color:#101820;">Args</span><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">	serviceProvider </span><span style="color:#68747D;">:=</span><span style="color:#68747D;"> &quot;&amp;admin.ServiceProvider{}&quot;</span></span>
<span class="line"><span style="color:#101820;">	moduleImport </span><span style="color:#68747D;">:=</span><span style="color:#68747D;"> &quot;admin &quot;</span><span style="color:#68747D;"> +</span><span style="color:#101820;"> setup</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Paths</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Module</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">Import</span><span style="color:#68747D;">()</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">	setup</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Install</span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#101820;">		modify</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">RegisterProvider</span><span style="color:#68747D;">(</span><span style="color:#101820;">moduleImport</span><span style="color:#68747D;">,</span><span style="color:#101820;"> serviceProvider</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">	).</span><span style="color:#0077B3;">Uninstall</span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#101820;">		modify</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">UnregisterProvider</span><span style="color:#68747D;">(</span><span style="color:#101820;">moduleImport</span><span style="color:#68747D;">,</span><span style="color:#101820;"> serviceProvider</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">	).</span><span style="color:#0077B3;">Execute</span><span style="color:#68747D;">()</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>After installation, the generated import uses the alias and the registered item can reference that alias:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">import </span><span style="color:#68747D;">(</span></span>
<span class="line"><span style="color:#101820;">	admin </span><span style="color:#68747D;">&quot;</span><span style="color:#101820;">github.com/example/goravel-admin</span><span style="color:#68747D;">&quot;</span></span>
<span class="line"><span style="color:#68747D;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#101820;">func </span><span style="color:#0077B3;">Providers</span><span style="color:#68747D;">()</span><span style="color:#68747D;"> []</span><span style="color:#101820;">foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">ServiceProvider </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">	return </span><span style="color:#68747D;">[]</span><span style="color:#101820;">foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">ServiceProvider</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">		&amp;</span><span style="color:#101820;">admin</span><span style="color:#68747D;">.</span><span style="color:#101820;">ServiceProvider</span><span style="color:#68747D;">{},</span></span>
<span class="line"><span style="color:#68747D;">	}</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Alias import strings are also supported by setup helpers that add and remove routes, middleware, commands, jobs, migrations, rules, filters, seeders, and service providers.</p><h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to “Resources”">​</a></h2><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h3><p>Typically, you will need to publish your package&#39;s configuration file to the application&#39;s <code>config</code> directory. This will allow users of your package to easily override your default configuration options. To allow your configuration files to be published, call the <code>Publishes</code> method from the <code>Boot</code> method of your service provider, the first parameter is the package name, and the second parameter is the mapping between the current package file path and the project path:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">receiver </span><span style="color:#68747D;">*</span><span style="color:#101820;">ServiceProvider</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Boot</span><span style="color:#68747D;">(</span><span style="color:#101820;">app foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">  app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Publishes</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;github.com/goravel/example-package&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;config/sms.go&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">ConfigPath</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;sms.go&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">  })</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="routes" tabindex="-1">Routes <a class="header-anchor" href="#routes" aria-label="Permalink to “Routes”">​</a></h3><p>If there are <a href="./../the-basics/routing.html">routes</a> in your package, you can use <code>app.MakeRoute()</code> to resolve <code>facades.Route()</code>, then add the routes to the project:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">receiver </span><span style="color:#68747D;">*</span><span style="color:#101820;">ServiceProvider</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Boot</span><span style="color:#68747D;">(</span><span style="color:#101820;">app foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">	route </span><span style="color:#68747D;">:=</span><span style="color:#101820;"> app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">MakeRoute</span><span style="color:#68747D;">()</span></span>
<span class="line"><span style="color:#101820;">	route</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Get</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;sms&quot;</span><span style="color:#68747D;">,</span><span style="color:#68747D;"> ***)</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to “Migrations”">​</a></h3><p>If there are <a href="./../database/migrations.html">migrations</a> in your package, you can publish them by the <code>Publishes</code> method:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">receiver </span><span style="color:#68747D;">*</span><span style="color:#101820;">ServiceProvider</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Boot</span><span style="color:#68747D;">(</span><span style="color:#101820;">app foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">  app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Publishes</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;github.com/goravel/example-package&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;migrations&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">DatabasePath</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;migrations&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">  })</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to “Models”">​</a></h3><p>If there are any new <a href="./../orm/getting-started.html">models</a> defined as part of your package, they can be published using the <code>Publishes</code> method:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">receiver </span><span style="color:#68747D;">*</span><span style="color:#101820;">ServiceProvider</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Boot</span><span style="color:#68747D;">(</span><span style="color:#101820;">app foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">  app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Publishes</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;github.com/goravel/example-package&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;models&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">ModelPath</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;models&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">  })</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to “Views”">​</a></h3><p>If your package provides default <a href="./../the-basics/views.html">views</a>, register their directory using <code>LoadViewsFrom</code> in your service provider&#39;s <code>Boot</code> method:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">receiver </span><span style="color:#68747D;">*</span><span style="color:#101820;">ServiceProvider</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Boot</span><span style="color:#68747D;">(</span><span style="color:#101820;">app foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">    facades</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">View</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">LoadViewsFrom</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;/path/to/package/views&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>The application&#39;s <code>resources/views</code> directory takes priority over registered package views, so users can override any package view by creating a file with the same name.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h2><p>You can register <code>Artisan</code> command by the <code>Commands</code> method, you can run the commands using <a href="./../digging-deeper/artisan-console.html">Artisan CLI</a> after registering them.</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">receiver </span><span style="color:#68747D;">*</span><span style="color:#101820;">ServiceProvider</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Boot</span><span style="color:#68747D;">(</span><span style="color:#101820;">app foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">	app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Commands</span><span style="color:#68747D;">([]</span><span style="color:#101820;">console</span><span style="color:#68747D;">.</span><span style="color:#101820;">Command</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">		commands</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">NewSmsCommand</span><span style="color:#68747D;">(),</span></span>
<span class="line"><span style="color:#68747D;">	})</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="public-assets" tabindex="-1">Public Assets <a class="header-anchor" href="#public-assets" aria-label="Permalink to “Public Assets”">​</a></h2><p>Your package may have assets such as JavaScript, CSS, and images. To publish these assets to the application&#39;s <code>public</code> directory, use the service provider&#39;s <code>Publishes</code> method:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">receiver </span><span style="color:#68747D;">*</span><span style="color:#101820;">ServiceProvider</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Boot</span><span style="color:#68747D;">(</span><span style="color:#101820;">app foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">  app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Publishes</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;github.com/goravel/example-package&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;public&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">PublicPath</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;vendor&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">  })</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="publishing-file-groups" tabindex="-1">Publishing File Groups <a class="header-anchor" href="#publishing-file-groups" aria-label="Permalink to “Publishing File Groups”">​</a></h2><p>If you want to publish specific groups of package assets and resources separately, you can use tags when calling the <code>Publishes</code> method from the package&#39;s service provider. This allows you to give users the option to publish certain files, like configuration files, without having to publish all the package&#39;s assets. To illustrate, you can define two publish groups for the <code>sms</code> package (<code>sms-config</code> and <code>sms-migrations</code>) using tags in the <code>Boot</code> method of the package&#39;s service provider.</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">receiver </span><span style="color:#68747D;">*</span><span style="color:#101820;">ServiceProvider</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Boot</span><span style="color:#68747D;">(</span><span style="color:#101820;">app foundation</span><span style="color:#68747D;">.</span><span style="color:#101820;">Application</span><span style="color:#68747D;">)</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">  app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Publishes</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;github.com/goravel/example-package&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;config/sms.go&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">ConfigPath</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;sms.go&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">  },</span><span style="color:#68747D;"> &quot;sms-config&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#101820;">  app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Publishes</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;github.com/goravel/example-package&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> map</span><span style="color:#68747D;">[</span><span style="color:#101820;">string</span><span style="color:#68747D;">]</span><span style="color:#101820;">string</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#68747D;">    &quot;migrations&quot;</span><span style="color:#68747D;">:</span><span style="color:#101820;"> app</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">DatabasePath</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;migrations&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">  },</span><span style="color:#68747D;"> &quot;sms-migrations&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="publish-resources" tabindex="-1">Publish Resources <a class="header-anchor" href="#publish-resources" aria-label="Permalink to “Publish Resources”">​</a></h2><p>In the project, You can publish the resources registered in a package using <code>vendor:publish</code> Artisan command:</p><div class="language-shell line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#0077B3;">./artisan</span><span style="color:#101820;"> vendor:publish</span><span style="color:#101820;"> --package=</span><span style="color:#101820;">{</span><span style="color:#0077B3;">You</span><span style="color:#101820;"> package</span><span style="color:#101820;"> name}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The command can use the following options:</p><table tabindex="0"><thead><tr><th>Option Name</th><th>Alias</th><th>Action</th></tr></thead><tbody><tr><td>--package</td><td>-p</td><td>Package name, can be a remote package: <code>github.com/goravel/example-package</code>, and also can be a local package: <code>./packages/example-package</code>, note that when using a local package name, it needs to start with <code>./</code>.</td></tr><tr><td>--tag</td><td>-t</td><td>Resource Group</td></tr><tr><td>--force</td><td>-f</td><td>Overwrite any existing files</td></tr><tr><td>--existing</td><td>-e</td><td>Publish and overwrite only the files that have already been published</td></tr></tbody></table>`,52)]))}const b=a(o,[["render",p]]);export{u as __pageData,b as default};
